[continuous time]
Exists(t_prime,
  AllOf(
    store(t_prime, non_volatile_memory_address_region_achievement, max_execution_time_measurement_data)
  )
)

[discrete time]
Exists(t1,
  ForAll(t2,
    Implies(
      calculate(t1, execution_time_measurement),
      Exists(v_max,
        AllOf(
          Cmp(Val(execution_time_measurement, t1), >=, Val(nv_memory_measuremt_block, t2))
        )
      )
    )
  )
)

[continuous time]
Exists(t_prime,
  AllOf(
    store(t_prime, non_volatile_memory, max_execution_time_measurement, measuremt_block_address)
  )
)

[discrete time]
Implies(
  Exists(t1,
    AllOf(
      read(t1, address_0xaa000018),
      Exists(t2,
        AllOf(
          store(t2, dtstcon_register, calibration_constant_value),
          Cmp(1.0, ==, Diff(t2, t1))
        )
      )
    )
  ),
  store(t2, dtstcon_register, calibration_constant_value)
)

[discrete time]
AllOf(
  read(t1, calibration_constant_signal, memory_storage.address(0xAA000018)),
  ForAll(t2,
    Implies(
      Cmp(Diff(t1, t2), <, 0.0),
      Not(
        store(t2, dtccon_storage.register(DTSCON), calibration_constant_signal)
      )
    )
  ),
  ForAll(t3,
    Implies(
      Cmp(Diff(t1, t3), >=, 0.0),
      store(t3, dtccon_storage.register(DTSCON), calibration_constant_signal)
    )
  )
)

[discrete time]
AllOf(
  read(t1, dtsc_address, calibration_constant_value),
  Implies(
    Exists(t2,
      Cmp(Val(dtsc_address, t1), =, Val(calibration_constant_value, t2))
    ),
    store(t2, dtsc_register, calibration_constant_value)
  )
)

[discrete time]
AllOf(
  read(t, calibration_storage_address_0xaa000018, calibration_constant_value),
  Implies(
    read(t, calibration_storage_address_0xaa000018, calibration_constant_value),
    Exists(v,
      store(t, dtsc_con_register, calibration_constant_value)
    )
  )
)
